import{_ as t,o as a,c as o,a2 as n}from"./chunks/framework.BZO4qERu.js";const u=JSON.parse('{"title":"OpenClaw","description":"Add Tokeness as a model provider in OpenClaw, configure OpenAI Compatible, Base URL, API key, and model name.","frontmatter":{"title":"OpenClaw","description":"Add Tokeness as a model provider in OpenClaw, configure OpenAI Compatible, Base URL, API key, and model name."},"headers":[],"relativePath":"integrations/openclaw.md","filePath":"integrations/openclaw.md","lastUpdated":1783700215000}'),s={name:"integrations/openclaw.md"};function i(d,e,l,r,p,c){return a(),o("div",null,[...e[0]||(e[0]=[n(`<h1 id="openclaw" tabindex="-1">OpenClaw <a class="header-anchor" href="#openclaw" aria-label="Permalink to &quot;OpenClaw&quot;">​</a></h1><p>OpenClaw supports adding model providers. To connect to Tokeness, configure it as an OpenAI Compatible provider.</p><h2 id="connection-details" tabindex="-1">Connection Details <a class="header-anchor" href="#connection-details" aria-label="Permalink to &quot;Connection Details&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Provider Name</td><td><code>Tokeness</code></td></tr><tr><td>API Type</td><td><code>OpenAI Compatible</code> or <code>OpenAI</code></td></tr><tr><td>Base URL</td><td><code>https://n.tokeness.io/v1</code></td></tr><tr><td>API Key</td><td>A key created in the Tokeness console</td></tr><tr><td>Model</td><td>Copied from the Tokeness model catalog</td></tr></tbody></table><h2 id="_1-prepare-tokeness" tabindex="-1">1. Prepare Tokeness <a class="header-anchor" href="#_1-prepare-tokeness" aria-label="Permalink to &quot;1. Prepare Tokeness&quot;">​</a></h2><p>Complete the following in the Tokeness console first:</p><ol><li>Confirm your balance is available.</li><li>Create a dedicated API key for OpenClaw.</li><li>Copy the model name you want to use.</li><li>Open the usage logs page.</li></ol><p>Name the key something like:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>openclaw-local</span></span></code></pre></div><h2 id="_2-open-openclaw-model-settings" tabindex="-1">2. Open OpenClaw Model Settings <a class="header-anchor" href="#_2-open-openclaw-model-settings" aria-label="Permalink to &quot;2. Open OpenClaw Model Settings&quot;">​</a></h2><p>Open the OpenClaw admin page and find the model, Config, Models, Provider, or Model Provider settings. The entry point name may differ across versions, but what you need to add is a &quot;model provider.&quot;</p><p>If OpenClaw offers a setup wizard, you can also choose a custom model provider in the wizard.</p><h2 id="_3-add-the-tokeness-provider" tabindex="-1">3. Add the Tokeness Provider <a class="header-anchor" href="#_3-add-the-tokeness-provider" aria-label="Permalink to &quot;3. Add the Tokeness Provider&quot;">​</a></h2><p>Create a new provider:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Name: Tokeness</span></span>
<span class="line"><span>API Type: OpenAI Compatible</span></span>
<span class="line"><span>Base URL: https://n.tokeness.io/v1</span></span>
<span class="line"><span>API Key: your Tokeness API key</span></span>
<span class="line"><span>Model: the model name copied from the Tokeness model catalog</span></span></code></pre></div><p>If OpenClaw distinguishes between Chat Model, Reasoning Model, and Small Model, you can fill them all with the same verified model first. Once it works, split them by task type.</p><p>If OpenClaw supports fetching a model list from <code>/v1/models</code>, you can try auto-fetch. If it fails, enter the model name manually.</p><h2 id="_4-save-and-enable" tabindex="-1">4. Save and Enable <a class="header-anchor" href="#_4-save-and-enable" aria-label="Permalink to &quot;4. Save and Enable&quot;">​</a></h2><p>After saving the provider, confirm that the current agent or default model has been switched to Tokeness.</p><p>Check two things:</p><ol><li>The provider has been saved.</li><li>The model configuration the current agent actually uses has Tokeness selected.</li></ol><p>Some tools do not automatically switch the default model after saving a provider — you need to select it again in the agent configuration.</p><h2 id="_5-verification" tabindex="-1">5. Verification <a class="header-anchor" href="#_5-verification" aria-label="Permalink to &quot;5. Verification&quot;">​</a></h2><p>Start a short task in OpenClaw:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Reply with a single sentence confirming OpenClaw is now connected to Tokeness.</span></span></code></pre></div><p>Then open the Tokeness usage logs:</p><ul><li>A new request means the request reached Tokeness.</li><li>The correct model name means the configuration took effect.</li><li>A successful status code means the key, balance, and model permissions are fine.</li></ul><h2 id="_6-multi-model-configuration" tabindex="-1">6. Multi-Model Configuration <a class="header-anchor" href="#_6-multi-model-configuration" aria-label="Permalink to &quot;6. Multi-Model Configuration&quot;">​</a></h2><p>Common OpenClaw scenarios can be split into multiple model sets:</p><table tabindex="0"><thead><tr><th>Configuration</th><th>Use case</th></tr></thead><tbody><tr><td>Main Model</td><td>Primary conversation, task planning</td></tr><tr><td>Coding Model</td><td>Code changes, project analysis</td></tr><tr><td>Fast Model</td><td>Simple replies, titles, summaries</td></tr><tr><td>Reasoning Model</td><td>Complex reasoning, long tasks</td></tr></tbody></table><p>Each model can use the same Tokeness Base URL — only the model name needs to differ.</p><h2 id="_7-keys-and-quota" tabindex="-1">7. Keys and Quota <a class="header-anchor" href="#_7-keys-and-quota" aria-label="Permalink to &quot;7. Keys and Quota&quot;">​</a></h2><p>OpenClaw is often used for long tasks and automation, so it is well suited to a dedicated key and quota.</p><p>Key management recommendations:</p><ul><li>Create a dedicated key for OpenClaw.</li><li>Set a smaller quota for the first connection.</li><li>Confirm the model price before running long tasks.</li><li>Check usage logs regularly for abnormal retries.</li><li>Do not upload the OpenClaw configuration directory to a public repository.</li></ul><h2 id="_8-troubleshooting" tabindex="-1">8. Troubleshooting <a class="header-anchor" href="#_8-troubleshooting" aria-label="Permalink to &quot;8. Troubleshooting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Action</th></tr></thead><tbody><tr><td>401 Unauthorized</td><td>The API key is wrong, disabled, or copied with extra spaces</td></tr><tr><td>403 Forbidden</td><td>Check the key group, quota, model permissions, or account status</td></tr><tr><td>404 Not Found</td><td>The Base URL should be <code>https://n.tokeness.io/v1</code></td></tr><tr><td>model not found</td><td>Re-copy the model name from the model catalog</td></tr><tr><td>Still uses the old model after saving</td><td>After saving the provider, also switch the model in the agent default settings</td></tr><tr><td>No Tokeness logs</td><td>The current OpenClaw agent is not using the Tokeness provider</td></tr><tr><td>Auto-fetch model list failed</td><td>Enter the model name manually</td></tr><tr><td>Long task interrupted</td><td>Check the model context, tool calls, balance, and timeout settings</td></tr></tbody></table>`,37)])])}const m=t(s,[["render",i]]);export{u as __pageData,m as default};
